class Solution {
public:
    ListNode* mergeNodes(ListNode* head) {
        ListNode* write=head;
        ListNode* cur=head->next;
        while(cur) {
            int sum=0;
            while(cur&&cur->val!=0){sum+=cur->val;cur=cur->next;}
            if(sum==0) break;
            write->val=sum;
            if(!cur||!cur->next){write->next=nullptr;break;}
            write->next=cur;write=cur;cur=cur->next;
        }
        return head;
    }
};
